    const additionalEntries = [
      {"term":"Faithfulness","category":"RAG Evaluation","meaning":"How well the claims in a generated answer are supported by the retrieved context.","example":"If the retrieved notes say the deadline is two weeks, an answer that says two weeks is faithful; saying three weeks lowers faithfulness.","related":["Groundedness","RAG","Hallucination"],"aliases":[],"whyItMatters":"A RAG system can retrieve the right evidence and still generate unsupported claims."},
      {"term":"Groundedness","category":"RAG Evaluation","meaning":"Whether a generated response stays anchored to the supplied context instead of inventing information.","example":"If the retrieved policy only mentions a 30-day return window, the answer should not invent a 60-day exception.","related":["Faithfulness","Grounding","Hallucination"],"aliases":[],"whyItMatters":"Grounded responses are easier to verify and safer to use in knowledge-heavy applications."},
      {"term":"Answer Relevance","category":"RAG Evaluation","meaning":"How directly the generated answer addresses the user's question.","example":"If the user asks for the required deadline, an answer that only repeats summary text without naming the deadline has low answer relevance.","related":["Context Relevance","RAG","Correctness"],"aliases":["Answer Relevancy"],"whyItMatters":"A factually correct answer can still be poor if it does not answer what the user asked."},
      {"term":"Context Relevance","category":"RAG Evaluation","meaning":"How useful the retrieved context is for answering the query.","example":"A refund question retrieves refund-policy passages rather than unrelated shipping documentation.","related":["Context Precision","Context Recall","RAG"],"aliases":["Context Relevancy"],"whyItMatters":"Irrelevant context wastes the context window and can distract the model."},
      {"term":"Context Precision","category":"RAG Evaluation","meaning":"How much of the retrieved context is relevant, with better-ranked relevant chunks generally scoring higher.","example":"If 8 of 10 retrieved chunks are useful and appear near the top, context precision is strong.","related":["Context Relevance","Precision@K","Reranker"],"aliases":[],"whyItMatters":"Higher precision gives the model cleaner evidence and reduces wasted context."},
      {"term":"Context Recall","category":"RAG Evaluation","meaning":"Whether retrieval found the information needed to produce the expected answer.","example":"A question asks for both the deadline and the required evidence, but retrieval returns only the deadline: recall is incomplete.","related":["Context Precision","Recall@K","RAG"],"aliases":[],"whyItMatters":"The model cannot use evidence that the retrieval stage never supplied."},
      {"term":"Response Completeness","category":"RAG Evaluation","meaning":"How completely the generated response covers the important information expected in the answer.","example":"The expected answer needs price, renewal date, and cancellation rules; giving only the price is incomplete.","related":["Answer Relevance","Correctness","Context Recall"],"aliases":["Completeness"],"whyItMatters":"A grounded answer can still fail if it omits critical details."},
      {"term":"Correctness","category":"RAG Evaluation","meaning":"How factually accurate the generated answer is compared with a trusted expected answer or ground truth.","example":"If the verified fee is $25 and the answer says $25, correctness is high; saying $20 is incorrect.","related":["Faithfulness","Ground Truth","Answer Relevance"],"aliases":["Answer Correctness"],"whyItMatters":"Faithfulness checks support from context; correctness checks whether the answer itself is actually right."},
      {"term":"Context Utilization","category":"RAG Evaluation","meaning":"How effectively the generated answer uses relevant information from the retrieved context.","example":"Five useful chunks are retrieved, but the answer uses facts from only one while missing the others.","related":["Context Relevance","Response Completeness","RAG"],"aliases":["Context Utilisation","Utilization"],"whyItMatters":"Good retrieval provides little value if the generation step ignores useful evidence."},
      {"term":"Citation Correctness","category":"RAG Evaluation","meaning":"Whether each citation actually supports the claim it is attached to.","example":"A sentence says the warranty is two years and cites a source that explicitly states two years: the citation is correct.","related":["Citation Completeness","Faithfulness","Groundedness"],"aliases":["Citation Accuracy"],"whyItMatters":"A response can look trustworthy while citing sources that do not support its claims."},
      {"term":"Citation Completeness","category":"RAG Evaluation","meaning":"Whether claims that require evidence are accompanied by citations.","example":"An answer makes five factual claims but cites evidence for only two of them: citation completeness is low.","related":["Citation Correctness","Groundedness","Faithfulness"],"aliases":[],"whyItMatters":"Complete citations make it easier for users to verify an answer."},
      {"term":"LLM-as-a-Judge","category":"RAG Evaluation","meaning":"Using a language model to score another model's response against an evaluation rubric.","example":"A judge model rates groundedness from 1 to 5 after reading the query, context, and answer.","related":["Evaluation","Ground Truth","Faithfulness"],"aliases":["LLM Judge"],"whyItMatters":"It scales evaluation of qualities that are difficult to capture with exact string metrics."},
      {"term":"Ground Truth","category":"RAG Evaluation","meaning":"Trusted reference data used as the expected answer or relevance label during evaluation.","example":"A reviewer writes the accepted answer and marks which source passages should count as relevant for a test question.","related":["Golden Dataset","Correctness","Recall@K"],"aliases":["Reference Answer"],"whyItMatters":"Reliable evaluation needs a trustworthy target to compare against."},
      {"term":"Golden Dataset","category":"RAG Evaluation","meaning":"A curated set of representative queries with trusted answers, contexts, or relevance labels for testing.","example":"A team keeps a fixed set of example questions and checked answers so it can compare retrieval quality over time.","related":["Ground Truth","Evaluation","RAG"],"aliases":["Evaluation Dataset","Eval Set"],"whyItMatters":"A stable test set lets teams compare RAG changes instead of relying on anecdotes."},
      {"term":"End-to-End RAG Evaluation","category":"RAG Evaluation","meaning":"Evaluating the complete RAG pipeline from user query through retrieval to the final generated answer.","example":"A test run scores retrieval quality, groundedness, relevance, completeness, latency, and cost for each query.","related":["RAG","Retrieval Evaluation","Faithfulness"],"aliases":["RAG Evaluation"],"whyItMatters":"A component can look good in isolation while the complete user experience still performs poorly."},
      {"term":"Retrieval Evaluation","category":"Retrieval Evaluation","meaning":"Measuring whether a search or RAG retriever returns the right documents in the right order.","example":"A test compares the top 10 retrieved chunks with expert-labelled relevant chunks.","related":["Precision@K","Recall@K","MRR","nDCG"],"aliases":[],"whyItMatters":"Generation quality is limited by the evidence the retriever provides."},
      {"term":"Precision@K","category":"Retrieval Evaluation","meaning":"The fraction of the top K retrieved results that are relevant.","example":"If 4 of the top 5 results are relevant, Precision@5 is 0.8.","related":["Recall@K","Context Precision","Top-K"],"aliases":["Precision at K","P@K"],"whyItMatters":"It measures how much useful material appears in the limited set sent downstream."},
      {"term":"Recall@K","category":"Retrieval Evaluation","meaning":"The fraction of all known relevant results that appear within the top K retrieved results.","example":"If 10 documents are relevant and 7 appear in the top 20, Recall@20 is 0.7.","related":["Precision@K","Context Recall","Top-K"],"aliases":["Recall at K","R@K"],"whyItMatters":"It shows whether retrieval is missing evidence the answer may need."},
      {"term":"Hit Rate","category":"Retrieval Evaluation","meaning":"The fraction of queries where at least one relevant result appears in the retrieved set.","example":"If 90 of 100 queries retrieve at least one relevant passage, hit rate is 90%.","related":["Recall@K","MRR","Retrieval Evaluation"],"aliases":["Hit@K","Hit Rate@K"],"whyItMatters":"It gives a simple view of whether retrieval succeeds at all for each query."},
      {"term":"MRR","category":"Retrieval Evaluation","meaning":"Mean Reciprocal Rank: how high the first relevant result appears across a set of queries.","example":"If the first relevant result is ranked 1st, its reciprocal rank is 1; if ranked 4th, it is 0.25.","related":["Hit Rate","nDCG","Retrieval Evaluation"],"aliases":["Mean Reciprocal Rank"],"whyItMatters":"MRR is useful when finding one strong result near the top matters most."},
      {"term":"nDCG","category":"Retrieval Evaluation","meaning":"Normalized Discounted Cumulative Gain: a ranking metric that rewards highly relevant results appearing near the top.","example":"A ranking with the best documents in positions 1 and 2 scores higher than one placing them at 8 and 9.","related":["MRR","MAP","Retrieval Evaluation"],"aliases":["Normalized Discounted Cumulative Gain","NDCG"],"whyItMatters":"It handles graded relevance and evaluates the quality of the whole ranking."},
      {"term":"MAP","category":"Retrieval Evaluation","meaning":"Mean Average Precision: the average ranking quality across all relevant results and across many queries.","example":"A retriever scores better when relevant documents repeatedly appear early instead of being scattered near the bottom.","related":["Precision@K","MRR","nDCG"],"aliases":["Mean Average Precision","MAP@K"],"whyItMatters":"MAP is useful when multiple relevant documents should rank well, not only the first one."},
      {"term":"Top-K","category":"RAG Configuration","meaning":"The maximum number of retrieval results kept for the next stage of a RAG pipeline.","example":"With top-k set to 5, the retriever returns its five highest-ranked chunks.","related":["Precision@K","Recall@K","Reranker"],"aliases":["Top K","K"],"whyItMatters":"A larger K can improve recall but also add noise, tokens, latency, and cost."},
      {"term":"Chunk Size","category":"RAG Configuration","meaning":"The amount of content placed in each chunk before documents are indexed for retrieval.","example":"A team tests 300-token, 600-token, and 1,000-token chunks to see which retrieves the most useful context.","related":["Chunking","Chunk Overlap","Context Window"],"aliases":[],"whyItMatters":"Chunks that are too small lose context; chunks that are too large can dilute relevance."},
      {"term":"Chunk Overlap","category":"RAG Configuration","meaning":"The amount of content repeated between neighboring chunks.","example":"Two 500-token chunks overlap by 50 tokens so a sentence crossing the boundary is not lost.","related":["Chunk Size","Chunking","RAG"],"aliases":[],"whyItMatters":"Overlap preserves boundary context but increases index size and duplicate retrieval."},
      {"term":"Similarity Threshold","category":"RAG Configuration","meaning":"A minimum similarity or relevance score a retrieved result must meet before being kept.","example":"Chunks below a cosine-similarity threshold are discarded instead of being sent to the model.","related":["Vector Similarity","Cosine Similarity","Top-K"],"aliases":["Score Threshold"],"whyItMatters":"Thresholds can filter weak results, but an overly strict threshold can hurt recall."},
      {"term":"Embedding Model","category":"RAG Configuration","meaning":"The model used to convert documents and queries into vectors for semantic retrieval.","example":"A multilingual embedding model is chosen because the knowledge base contains English, French, and Spanish documents.","related":["Embedding","Vector Database","Semantic Search"],"aliases":[],"whyItMatters":"Embedding quality strongly affects which content the retriever considers similar."},
      {"term":"Vector Similarity","category":"RAG Configuration","meaning":"A numerical measure of how close two embedding vectors are.","example":"The query vector is compared with document vectors and the closest matches are ranked first.","related":["Embedding","Cosine Similarity","Vector Database"],"aliases":["Similarity Metric"],"whyItMatters":"The similarity method determines how vector search ranks candidate documents."},
      {"term":"Cosine Similarity","category":"RAG Configuration","meaning":"A vector similarity measure based on the angle between two vectors rather than their magnitude.","example":"Two passages with embeddings pointing in nearly the same direction receive a cosine similarity close to 1.","related":["Vector Similarity","Embedding","Similarity Threshold"],"aliases":[],"whyItMatters":"Cosine similarity is commonly used for semantic search with text embeddings."},
      {"term":"Query Rewriting","category":"RAG Configuration","meaning":"Rephrasing a user's query into a form that is easier for the retrieval system to search.","example":"'Why won't it work?' becomes 'Troubleshooting failed deployment steps for a local service' using the prior conversation context.","related":["Query Expansion","Hybrid Search","Semantic Search"],"aliases":["Query Rewrite"],"whyItMatters":"User questions are often vague, conversational, or poorly matched to document wording."},
      {"term":"Query Expansion","category":"RAG Configuration","meaning":"Adding related words, synonyms, or subqueries to improve retrieval coverage.","example":"A search for 'login' is expanded with 'sign in', 'authentication', and related terms to find more relevant passages.","related":["Query Rewriting","Recall@K","Hybrid Search"],"aliases":[],"whyItMatters":"Expansion can improve recall when users and documents describe the same concept differently."},
      {"term":"Metadata Filtering","category":"RAG Configuration","meaning":"Restricting retrieval using document metadata such as date, language, document type, or access level.","example":"A search only includes records from the current year and the user's allowed document set.","related":["RAG","Vector Database","Least Privilege"],"aliases":["Metadata Filter"],"whyItMatters":"Filtering improves relevance and can enforce important data-access boundaries."},
      {"term":"RRF","category":"RAG Configuration","meaning":"Reciprocal Rank Fusion: a method for combining multiple ranked result lists into one ranking.","example":"Keyword and vector search each return results; RRF merges their rankings into a single list.","related":["Hybrid Search","Reranker","Retrieval Evaluation"],"aliases":["Reciprocal Rank Fusion"],"whyItMatters":"RRF lets different retrieval strategies contribute without requiring directly comparable scores."},
      {"term":"Context Window Allocation","category":"RAG Configuration","meaning":"How much of the model's available context window is reserved for retrieved evidence versus instructions, history, and output.","example":"An application reserves 20,000 tokens for retrieved documents and leaves the rest for conversation and generation.","related":["Context Window","Top-K","Token Usage"],"aliases":["Context Budget"],"whyItMatters":"Overfilling context can increase cost and reduce the model's ability to focus on the most useful evidence."},
      {"term":"RAG Latency","category":"RAG Operations","meaning":"The total time required to retrieve context and generate the final RAG response.","example":"Retrieval takes 120 ms, reranking 180 ms, and generation 1.2 s, producing about 1.5 s total latency.","related":["Latency","Reranker","RAG"],"aliases":[],"whyItMatters":"Extra retrieval and reranking stages can improve quality while making the application feel slower."},
      {"term":"Token Usage","category":"RAG Operations","meaning":"The number of model input and output tokens consumed while answering a query.","example":"Retrieving ten large chunks produces 12,000 input tokens before the model writes a 500-token answer.","related":["Token","Context Window Allocation","Cost per Query"],"aliases":["Token Consumption"],"whyItMatters":"More retrieved context usually increases model cost and can increase latency."},
      {"term":"Cost per Query","category":"RAG Operations","meaning":"The total cost of serving one RAG request across retrieval, reranking, embeddings, and model generation.","example":"A team compares $0.002 and $0.02 pipelines to see whether the quality improvement justifies the extra cost.","related":["Token Usage","RAG Latency","RAG"],"aliases":["Cost per Request"],"whyItMatters":"A high-quality pipeline still needs sustainable economics at production traffic levels."}
    ];

